  'dalle-precision': { s: 'Devant une voie facile que tu peux monter puis redescendre, chaussons serrés, première prise de pied repérée.', e: 'Prises de pied plus grosses.', h: 'Vise un point précis de la prise (bord, pointe) avant chaque mouvement.' },
  'dalle-equilibre-un-pied': { s: 'Debout sur une prise de pied large, mains sur deux prises faciles à hauteur d’épaules, bassin au-dessus du pied porteur.', e: 'Tiens 1 s seulement, ou garde un doigt de chaque main sur le mur.', h: 'Prise de pied plus petite, ou lâche une main.' },
  'dalle-lente': { s: 'Sur une voie facile de dalle ou verticale, bras tendus, hanches proches du mur.', e: 'Prises plus grosses et pauses sur les repos.', h: '3 s par mouvement sur un terrain plus raide.' },
