  'hang-repeaters': { s: 'Comme pour les suspensions : réglette confortable (20–25 mm), demi-arqué, bras tendus, épaules engagées.', l: 'En général sans lest. Si c’est trop facile : ceinture de lest avec 2 à 5 kg. Pour alléger : pieds sur une chaise ou élastique.', e: 'Prise plus grosse, ou 5 suspensions au lieu de 6.', h: 'Prise plus petite, ou un peu de lest.' },
  'wall-reglettes': { s: 'Choisis 4 à 6 blocs à réglettes, 1 à 2 niveaux sous ton max, avec de bons pieds ; doigts déjà échauffés.', e: 'Réglettes plus grosses.', h: 'Réglettes plus fines ou pieds moins bons.' },
  'wall-traverse-reglettes': { s: 'Pied du mur, traversée basse sur réglettes larges et bons pieds ; doigts déjà échauffés.', e: 'Ajoute des prises plus grosses sur le trajet.', h: 'Allonge la durée, ou prends des réglettes plus fines.' },
  'finger-extensions': { s: 'Passe un élastique épais autour des cinq doigts réunis, main détendue, coude plié devant toi.', l: 'La résistance vient de l’élastique : prends-en un plus épais ou double-le pour durcir.', e: 'Élastique plus fin.', h: 'Élastique plus épais, ouverture en 3 s et retour en 3 s.' },
  'wrist-extension': { s: 'Assis, avant-bras posé sur la cuisse ou une table, la main dépasse dans le vide, paume vers le bas.', l: 'Un haltère court ou une bouteille d’eau tenu dans la main, au bout de l’appui ; commence très léger (0,5 à 2 kg).', e: 'Sans poids, juste le mouvement.', h: 'Descente plus lente (3 s).' },
  'wu-fingers': { s: 'Debout sous la poutre, mains sur la plus grosse prise, pieds au sol ou sur une chaise pour doser l’effort.', l: 'Pas de charge : ce sont les pieds qui dosent (plus ils portent, plus c’est léger).' },
