  'limit-boulders': { s: 'Choisis 2 ou 3 blocs à ton max, après un échauffement complet ; repos complet entre les essais.', e: 'Blocs un niveau sous ton max.', h: 'Blocs au-dessus de ton max, en travaillant les mouvements séparément.' },
  'speed-known': { s: 'Une voie connue, 3 niveaux sous ton max, assureur prêt, chrono lancé au départ.', e: 'Voie plus facile, sans chrono.', h: 'Gagne quelques secondes sans perdre en précision.' },
