  'four-by-four': { s: 'Choisis 4 blocs 2 niveaux sous ton max, proches les uns des autres ; échauffé.', e: 'Blocs plus faciles, ou 3 blocs.', h: 'Blocs plus durs, ou moins de repos entre les séries.' },
  'endurance-intervals': { s: 'Une voie ou une traversée facile, un chrono visible (3 min de grimpe, 3 min de repos).', e: '2 min de grimpe pour 3 min de repos.', h: '4 min de grimpe, ou un terrain un peu plus raide.' },
  'endurance-circuit': { s: 'Prépare la barre (basse pour les tractions australiennes), un tapis et un chrono, tout à portée de main.', e: 'Moins de répétitions (6 de chaque).', h: 'Un tour de plus, ou moins de pause entre les tours.' },
