  'explosive-pullup': { s: 'Suspendu à la barre, bras tendus, épaules engagées, jambes serrées.', e: 'Avec un élastique d’aide.', h: 'Monte la poitrine jusqu’à la barre.' },
  'scap-pullup': { s: 'Suspendu à la barre, bras tendus, mains largeur d’épaules, épaules relâchées vers les oreilles.', e: 'Pieds sur une chaise pour alléger.', h: 'Pause de 2 s épaules basses, ou un peu de lest.' },
